"""Current Package Manager routes; historical classroom ZIP metadata is retained separately."""
from pathlib import Path
import html,json
SITE=Path(__file__).resolve().parents[2]/'docs/manual'

STYLE='<style>.manual-release-downloads table{width:100%;border-collapse:collapse}.manual-release-downloads th,.manual-release-downloads td{padding:.65rem .8rem;text-align:left;vertical-align:top;border-bottom:1px solid #cbdad3}.manual-release-downloads th:first-child,.manual-release-downloads td:first-child{padding-left:0}.manual-release-downloads th:last-child,.manual-release-downloads td:last-child{padding-right:0}@media(max-width:650px){.manual-release-downloads thead{display:none}.manual-release-downloads tr{display:block;padding:.8rem 0;border-bottom:1px solid #cbdad3}.manual-release-downloads td{display:block;padding:.15rem 0;border:0}.manual-release-downloads td:first-child{font-weight:700}}</style>'

def release_downloads():
 data=json.loads((SITE/'data/release.json').read_text(encoding='utf-8'))
 rows=''.join('<tr><td>'+html.escape(p['platform'])+'</td><td><code>'+html.escape(p['version'])+'</code></td><td>'+html.escape(p['requirements'])+'</td><td>'+html.escape(p['scope'])+'</td></tr>' for p in data['yak_packages'])
 return STYLE+'<section class="manual-related manual-release-downloads" id="classroom-downloads"><h2>Install from Rhino Package Manager</h2><p>Run <code>_PackageManager</code> → Online → enable <strong>Include pre-releases</strong> → search <code>topoptlab-rhino</code> → select the version for your platform → Install. Restart Rhino, then right-click a TopOptLab component and open the Python setup folder. Run <code>SETUP-PYTHON.cmd</code> on Windows or <code>SETUP-PYTHON.command</code> on Mac.</p><div class="table-wrap"><table><thead><tr><th>Computer</th><th>Yak version</th><th>Requirements</th><th>Validation scope</th></tr></thead><tbody>'+rows+'</tbody></table></div><p><strong>Mac alpha: loading and using the GHA inside Rhino/Grasshopper for Mac remains untested.</strong> CPU-worker tests do not establish native application compatibility. The package contains this complete English manual, HTML lesson slides and exercise files under <code>source/</code>. The historical classroom ZIP release is still a draft; no private ZIP download is needed for this route. PowerPoint files are not included.</p></section>'
